  let lo = 0;
  let hi = events.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if ((events[mid]?.ts ?? 0) < from) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}
