  covariates: readonly string[],
  treated: number[][],
  control: number[][],
): BalanceRow[] {
  return covariates.map((c, j) => ({
    covariate: c,
    smd: smd(treated.map((r) => r[j] ?? 0), control.map((r) => r[j] ?? 0)),
