export function rollingHie(
  windows: readonly { name: string; hie: number }[][],
  halfLife = 2,
): Map<string, number> {
  const out = new Map<string, number>();
  const decay = Math.pow(0.5, 1 / halfLife);
  for (const win of windows) {
    for (const { name, hie } of win) {
